<?php defined('ABSPATH') || exit; get_header(); $content = hubby_content(); $intro = $content['experience']['intro'] ?? $content['shop'] ?? []; ?>
<main id="main"><section class="container hero"><div><div class="eyebrow"><?php echo esc_html(get_theme_mod('hubby_eyebrow', $intro['eyebrow'] ?? 'HUBBY')); ?></div><h1><?php echo esc_html(get_theme_mod('hubby_title', $intro['title'] ?? get_bloginfo('name'))); ?><br><span><?php echo esc_html(get_theme_mod('hubby_accent', $intro['accent'] ?? '')); ?></span></h1><p><?php echo esc_html(get_theme_mod('hubby_description', $intro['description'] ?? '')); ?></p><div class="actions"><a class="button" href="#san-pham">Khám phá sản phẩm</a><a class="button secondary" href="#ho-tro">Hỏi Hubby</a></div></div>
<?php
$slides = array_values(array_filter($content['experience']['slides'] ?? [], static fn($slide) => !empty($slide['media']['src'])));
if (!$slides && !array_key_exists('slides', $content['experience'] ?? [])) {
    $slides = [ ['media' => ['src' => '/visuals/welcome-1200.webp', 'alt' => 'Hubby — tài khoản và dịch vụ số'], 'href' => '/#san-pham'], ['media' => ['src' => '/visuals/students-1200.webp', 'alt' => 'Ưu đãi sinh viên HUB — hỏi Hubby về điều kiện áp dụng'], 'href' => '/#ho-tro'], ['media' => ['src' => '/visuals/digital-1200.webp', 'alt' => 'Chọn gói bạn cần'], 'href' => '/#san-pham'] ];
} elseif (!$slides && !empty($content['experience']['slides'])) {
    // Match the existing storefront's non-mutating fallback for configured
    // legacy slides with no uploaded media. Explicit [] remains empty.
    $slides = [ ['media' => ['src' => '/visuals/welcome-1200.webp', 'alt' => 'Hubby — tài khoản và dịch vụ số'], 'href' => '/#san-pham'], ['media' => ['src' => '/visuals/students-1200.webp', 'alt' => 'Ưu đãi sinh viên HUB — hỏi Hubby về điều kiện áp dụng'], 'href' => '/#ho-tro'], ['media' => ['src' => '/visuals/digital-1200.webp', 'alt' => 'Chọn gói bạn cần'], 'href' => '/#san-pham'] ];
}
?>
<?php if (get_option('hubby_native_content_imported') && function_exists('hubby_home_banners')) $slides = hubby_home_banners(); ?>
<?php if ($slides): ?><div class="banner-stack" aria-label="Banner nổi bật"><?php foreach ($slides as $i => $slide): ?><a class="banner <?php echo $i === 0 ? 'active' : ''; ?>" <?php echo $i !== 0 ? 'hidden' : ''; ?> href="<?php echo esc_url(hubby_source_url($slide['href'])); ?>"><img src="<?php echo esc_url(hubby_source_url($slide['media']['src'])); ?>" alt="<?php echo esc_attr($slide['media']['alt']); ?>" width="1200" height="800"></a><?php endforeach; ?><div class="banner-controls"><?php foreach ($slides as $i => $slide): ?><button type="button" aria-label="Banner <?php echo absint($i + 1); ?>" aria-current="<?php echo $i === 0 ? 'true' : 'false'; ?>" data-slide="<?php echo absint($i); ?>"></button><?php endforeach; ?></div><button type="button" class="pause-banner button">Tạm dừng banner</button></div><?php endif; ?></section>
<?php if (!empty($content['steps'])): ?><section class="container steps" aria-label="Cách mua hàng"><?php foreach ($content['steps'] as $i => $step): ?><article class="step"><strong>0<?php echo absint($i + 1); ?></strong><h3><?php echo esc_html($step['title']); ?></h3><p><?php echo esc_html($step['description']); ?></p></article><?php endforeach; ?></section><?php endif; ?>
<section class="container catalog woocommerce" id="san-pham"><div class="section-title"><div><div class="eyebrow">SẢN PHẨM</div><h2>Chọn gói bạn cần</h2></div><a href="<?php echo esc_url(wc_get_page_permalink('shop')); ?>">Xem tất cả →</a></div><nav class="category-nav" aria-label="Danh mục sản phẩm"><?php foreach (get_terms(['taxonomy' => 'product_cat', 'hide_empty' => true]) as $term): ?><a href="<?php echo esc_url(get_term_link($term)); ?>"><?php echo esc_html($term->name); ?></a><?php endforeach; ?></nav><?php echo do_shortcode('[products limit="12" columns="3" orderby="menu_order" order="ASC"]'); ?></section>
<?php $faqs = get_option('hubby_native_content_imported') && function_exists('hubby_home_faqs') ? hubby_home_faqs() : ($content['faqs'] ?? []); ?>
<?php if ($faqs): ?><section class="container faq" id="faq"><div class="eyebrow">FAQ</div><h2>Câu hỏi thường gặp.</h2><?php foreach ($faqs as $faq): ?><details><summary><?php echo esc_html($faq['question']); ?></summary><div><?php echo wp_kses_post(wpautop($faq['answer'])); ?></div></details><?php endforeach; ?></section><?php endif; ?>
<section class="container support" id="ho-tro"><h2><?php echo esc_html(get_theme_mod('hubby_support_title', $content['support']['title'] ?? 'Bạn cần hỗ trợ?')); ?></h2><p><?php echo esc_html(get_theme_mod('hubby_support_description', $content['support']['description'] ?? '')); ?></p><?php $facebook = get_theme_mod('hubby_facebook', $content['support']['fanpageUrl'] ?? ''); if ($facebook): ?><a class="button" href="<?php echo esc_url($facebook); ?>" rel="noopener noreferrer" target="_blank">Liên hệ Facebook</a><?php else: ?><a class="button" href="<?php echo esc_url(wc_get_page_permalink('myaccount')); ?>">Tài khoản & đơn hàng</a><?php endif; ?></section></main><?php get_footer(); ?>
